-- ---------------------------------------------------------------------------
-- 6. Driver route execution RPCs
-- ---------------------------------------------------------------------------
-- Live ETAs: re-time every open stop from where the driver is now (fresh GPS),
-- else the last closed stop, else the hub. 30 km/h urban average, ×1.3 road
-- factor, 5 min service per stop. Called after each stop update, on route
-- start, and by the dispatch sweep for routes on the road.
CREATE OR REPLACE FUNCTION public.route_refresh_etas(p_route_id UUID)
RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_route public.delivery_routes;
  v_lat NUMERIC;
  v_lng NUMERIC;
  v_clock TIMESTAMPTZ := now();
  v_km NUMERIC;
  r RECORD;
BEGIN
  SELECT * INTO v_route FROM public.delivery_routes WHERE id = p_route_id;
  IF v_route.id IS NULL OR v_route.status <> 'in_progress' THEN
    RETURN;
  END IF;

  SELECT latitude, longitude INTO v_lat, v_lng FROM public.driver_locations
   WHERE driver_id = v_route.driver_id AND last_updated > now() - interval '10 minutes';
  IF v_lat IS NULL THEN
    SELECT lat, lng INTO v_lat, v_lng FROM public.route_stops
     WHERE route_id = p_route_id AND status IN ('completed', 'failed', 'skipped') AND lat IS NOT NULL
     ORDER BY sequence DESC LIMIT 1;
  END IF;
  IF v_lat IS NULL THEN
    SELECT h.lat, h.lng INTO v_lat, v_lng FROM public.logistics_hubs h WHERE h.id = v_route.hub_id;
  END IF;

  FOR r IN
    SELECT id, lat, lng, status FROM public.route_stops
     WHERE route_id = p_route_id AND status IN ('pending', 'arrived')
     ORDER BY sequence
  LOOP
    IF r.status = 'arrived' THEN
      UPDATE public.route_stops SET eta = now() WHERE id = r.id;
      v_clock := now() + interval '5 minutes';
    ELSE
      IF r.lat IS NOT NULL AND v_lat IS NOT NULL THEN
        v_km := 2 * 6371 * asin(sqrt(
          power(sin(radians(r.lat - v_lat) / 2), 2) +
          cos(radians(v_lat)) * cos(radians(r.lat)) * power(sin(radians(r.lng - v_lng) / 2), 2))) * 1.3;
        v_clock := v_clock + make_interval(secs => (v_km / 30.0) * 3600);
      END IF;
      UPDATE public.route_stops SET eta = v_clock WHERE id = r.id;
      v_clock := v_clock + interval '5 minutes';
    END IF;
    IF r.lat IS NOT NULL THEN
      v_lat := r.lat;
      v_lng := r.lng;
    END IF;
  END LOOP;
END;
$$;

CREATE OR REPLACE FUNCTION public.driver_start_route(p_route_id UUID)
RETURNS public.delivery_routes
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_route public.delivery_routes;
  v_driver UUID;
BEGIN
  SELECT id INTO v_driver FROM public.drivers WHERE user_id = auth.uid();
  SELECT * INTO v_route FROM public.delivery_routes WHERE id = p_route_id FOR UPDATE;

  IF v_route.id IS NULL OR v_driver IS NULL OR v_route.driver_id IS DISTINCT FROM v_driver THEN
    RAISE EXCEPTION 'route_not_assigned' USING ERRCODE = '42501';
  END IF;
  IF v_route.status = 'in_progress' THEN
    RETURN v_route;
  END IF;
  IF v_route.status <> 'dispatched' THEN
    RAISE EXCEPTION 'route_not_dispatched';
  END IF;

  PERFORM set_config('logistics.event_driver', v_driver::text, true);
  PERFORM set_config('logistics.event_notes', 'Out for delivery on route ' || v_route.name, true);

  -- Parcels already in the driver's hands go out for delivery.
  UPDATE public.shipments s
     SET status = 'out_for_delivery', current_hub_id = NULL
    FROM public.route_stops rs
   WHERE rs.route_id = p_route_id AND rs.stop_type = 'delivery'
     AND rs.shipment_id = s.id AND s.status IN ('at_hub', 'picked_up', 'failed_attempt');

  UPDATE public.delivery_routes
     SET status = 'in_progress', started_at = now()
   WHERE id = p_route_id
   RETURNING * INTO v_route;

  UPDATE public.drivers SET status = 'busy' WHERE id = v_driver;
  PERFORM public.route_refresh_etas(p_route_id);
  RETURN v_route;
END;
$$;

CREATE OR REPLACE FUNCTION public.driver_update_stop(
  p_stop_id UUID,
  p_action TEXT,
  p_failure_reason TEXT DEFAULT NULL,
  p_otp TEXT DEFAULT NULL,
  p_proof JSONB DEFAULT NULL,
  p_lat NUMERIC DEFAULT NULL,
  p_lng NUMERIC DEFAULT NULL,
  -- When the action really happened (offline sync). Clamped to the last 24 h.
  p_occurred_at TIMESTAMPTZ DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_stop public.route_stops;
  v_route public.delivery_routes;
  v_ship public.shipments;
  v_driver UUID;
  v_new_attempts INTEGER;
  v_at TIMESTAMPTZ := GREATEST(LEAST(COALESCE(p_occurred_at, now()), now()), now() - interval '24 hours');
BEGIN
  IF p_action NOT IN ('arrive', 'complete', 'fail', 'skip') THEN
    RAISE EXCEPTION 'invalid_action';
  END IF;

  SELECT id INTO v_driver FROM public.drivers WHERE user_id = auth.uid();
  SELECT * INTO v_stop FROM public.route_stops WHERE id = p_stop_id FOR UPDATE;
  SELECT * INTO v_route FROM public.delivery_routes WHERE id = v_stop.route_id FOR UPDATE;

  IF v_stop.id IS NULL OR v_driver IS NULL OR v_route.driver_id IS DISTINCT FROM v_driver THEN
    RAISE EXCEPTION 'stop_not_assigned' USING ERRCODE = '42501';
  END IF;
  IF v_route.status <> 'in_progress' THEN
    RAISE EXCEPTION 'route_not_started';
  END IF;
  IF v_stop.status IN ('completed', 'failed', 'skipped') THEN
    RAISE EXCEPTION 'stop_already_closed';
  END IF;

  IF v_stop.shipment_id IS NOT NULL THEN
    SELECT * INTO v_ship FROM public.shipments WHERE id = v_stop.shipment_id FOR UPDATE;
  END IF;

  PERFORM set_config('logistics.event_driver', v_driver::text, true);
  PERFORM set_config('logistics.event_lat', COALESCE(p_lat::text, ''), true);
  PERFORM set_config('logistics.event_lng', COALESCE(p_lng::text, ''), true);

  IF p_action = 'arrive' THEN
    UPDATE public.route_stops SET status = 'arrived', arrived_at = v_at
     WHERE id = p_stop_id RETURNING * INTO v_stop;
    RETURN jsonb_build_object('ok', true, 'stop', to_jsonb(v_stop));
  END IF;

  IF p_action = 'complete' THEN
    IF v_stop.stop_type = 'delivery' AND v_ship.id IS NOT NULL AND v_ship.require_otp THEN
      -- Brute-force guard: 5 wrong codes lock the parcel until dispatch resets it.
      -- Returned (not raised) so the failure count is committed.
      IF v_ship.otp_failures >= 5 THEN
        RETURN jsonb_build_object('ok', false, 'error', 'otp_locked');
      END IF;
      IF p_otp IS NULL OR p_otp <> v_ship.delivery_otp THEN
        UPDATE public.shipments SET otp_failures = otp_failures + 1 WHERE id = v_ship.id;
        RETURN jsonb_build_object('ok', false, 'error',
          CASE WHEN v_ship.otp_failures + 1 >= 5 THEN 'otp_locked' ELSE 'invalid_otp' END,
          'attempts_left', GREATEST(4 - v_ship.otp_failures, 0));
      END IF;
    END IF;

    UPDATE public.route_stops
       SET status = 'completed', completed_at = v_at,
           arrived_at = COALESCE(arrived_at, v_at), proof = p_proof
     WHERE id = p_stop_id RETURNING * INTO v_stop;

    IF v_ship.id IS NOT NULL THEN
      IF v_stop.stop_type = 'pickup' THEN
        PERFORM set_config('logistics.event_notes', 'Collected by driver', true);
        -- Same-route delivery => straight out for delivery; otherwise it is
        -- in the driver's hands awaiting a hub drop or a later route.
        UPDATE public.shipments
           SET picked_up_at = v_at,
               status = CASE WHEN EXISTS (
                 SELECT 1 FROM public.route_stops
                  WHERE route_id = v_route.id AND shipment_id = v_ship.id AND stop_type = 'delivery'
               ) THEN 'out_for_delivery' ELSE 'picked_up' END
         WHERE id = v_ship.id;
      ELSIF v_stop.stop_type = 'delivery' THEN
        PERFORM set_config('logistics.event_notes',
          'Delivered' || COALESCE(' — received by ' || (p_proof->>'received_by'), ''), true);
        UPDATE public.shipments SET status = 'delivered', delivered_at = v_at
         WHERE id = v_ship.id;
      ELSIF v_stop.stop_type = 'hub' THEN
        -- Final hop to the customer's pickup point / locker → ready for collection.
        IF v_ship.destination_hub_id = v_stop.hub_id AND EXISTS (
             SELECT 1 FROM public.logistics_hubs h WHERE h.id = v_stop.hub_id AND h.hub_type IN ('pickup_point', 'locker')) THEN
          PERFORM set_config('logistics.event_notes', 'Ready for collection', true);
          UPDATE public.shipments
             SET status = 'ready_for_collection', current_hub_id = v_stop.hub_id, collect_by = v_at + interval '7 days'
           WHERE id = v_ship.id;
        ELSE
          PERFORM set_config('logistics.event_notes', 'Dropped at hub', true);
          UPDATE public.shipments SET status = 'at_hub', current_hub_id = v_stop.hub_id
           WHERE id = v_ship.id;
        END IF;
      END IF;
    END IF;

    IF v_stop.delivery_job_id IS NOT NULL THEN
      UPDATE public.delivery_jobs
         SET status = CASE WHEN v_stop.stop_type = 'pickup' THEN 'picked_up' ELSE 'delivered' END,
             pickup_time = CASE WHEN v_stop.stop_type = 'pickup' THEN v_at ELSE pickup_time END,
             actual_delivery_time = CASE WHEN v_stop.stop_type = 'delivery' THEN v_at ELSE actual_delivery_time END
       WHERE id = v_stop.delivery_job_id;
    END IF;
  END IF;

  IF p_action IN ('fail', 'skip') THEN
    IF p_action = 'fail' AND COALESCE(trim(p_failure_reason), '') = '' THEN
      RAISE EXCEPTION 'failure_reason_required';
    END IF;

    UPDATE public.route_stops
       SET status = CASE WHEN p_action = 'fail' THEN 'failed' ELSE 'skipped' END,
           completed_at = v_at, failure_reason = p_failure_reason, proof = p_proof
     WHERE id = p_stop_id RETURNING * INTO v_stop;

    IF p_action = 'fail' AND v_ship.id IS NOT NULL THEN
      v_new_attempts := v_ship.attempt_count + 1;
      PERFORM set_config('logistics.event_notes', p_failure_reason, true);
      UPDATE public.shipments
         SET attempt_count = CASE WHEN v_stop.stop_type = 'delivery' THEN v_new_attempts ELSE attempt_count END,
             last_failure_reason = p_failure_reason,
             status = CASE
               WHEN v_stop.stop_type = 'pickup' THEN 'exception'
               WHEN v_new_attempts >= v_ship.max_attempts THEN 'returning'
               ELSE 'failed_attempt'
             END
       WHERE id = v_ship.id;
    END IF;

    IF p_action = 'fail' AND v_stop.delivery_job_id IS NOT NULL THEN
      UPDATE public.delivery_jobs
         SET status = 'failed', failure_reason = p_failure_reason, attempt_count = attempt_count + 1
       WHERE id = v_stop.delivery_job_id;
    END IF;
  END IF;

  -- Close the route once every stop is resolved.
  IF NOT EXISTS (
    SELECT 1 FROM public.route_stops
     WHERE route_id = v_route.id AND status IN ('pending', 'arrived')
  ) THEN
    UPDATE public.delivery_routes SET status = 'completed', completed_at = v_at WHERE id = v_route.id;
    UPDATE public.drivers SET status = 'available', total_deliveries = COALESCE(total_deliveries, 0) + (
      SELECT count(*) FROM public.route_stops
       WHERE route_id = v_route.id AND stop_type = 'delivery' AND status = 'completed'
    ) WHERE id = v_driver;
  END IF;

  PERFORM public.route_refresh_etas(v_route.id);
  RETURN jsonb_build_object('ok', true, 'stop', to_jsonb(v_stop));
END;
$$;

GRANT EXECUTE ON FUNCTION public.driver_start_route(UUID) TO authenticated;
GRANT EXECUTE ON FUNCTION public.driver_update_stop(UUID, TEXT, TEXT, TEXT, JSONB, NUMERIC, NUMERIC, TIMESTAMPTZ) TO authenticated;

-- ---------------------------------------------------------------------------
-- 7. Team management RPCs (owner only)
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.logistics_list_members()
RETURNS TABLE (id UUID, user_id UUID, email TEXT, role TEXT, hub_id UUID, is_active BOOLEAN, created_at TIMESTAMPTZ)
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public
AS $$
BEGIN
  IF NOT public.is_logistics_staff(ARRAY['owner']) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  RETURN QUERY
    SELECT m.id, m.user_id, u.email::text, m.role, m.hub_id, m.is_active, m.created_at
      FROM public.logistics_members m
      JOIN auth.users u ON u.id = m.user_id
     ORDER BY m.created_at;
END;
$$;

CREATE OR REPLACE FUNCTION public.logistics_upsert_member(p_email TEXT, p_role TEXT, p_hub_id UUID DEFAULT NULL)
RETURNS UUID
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_user UUID;
  v_id UUID;
BEGIN
  IF NOT public.is_logistics_staff(ARRAY['owner']) THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  SELECT u.id INTO v_user FROM auth.users u WHERE lower(u.email) = lower(trim(p_email)) LIMIT 1;
  IF v_user IS NULL THEN
    RAISE EXCEPTION 'user_not_found';
  END IF;
  INSERT INTO public.logistics_members (user_id, role, hub_id, invited_by)
  VALUES (v_user, p_role, p_hub_id, auth.uid())
  ON CONFLICT (user_id) DO UPDATE
    SET role = EXCLUDED.role, hub_id = EXCLUDED.hub_id, is_active = true
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.logistics_list_members() TO authenticated;
GRANT EXECUTE ON FUNCTION public.logistics_upsert_member(TEXT, TEXT, UUID) TO authenticated;

-- ---------------------------------------------------------------------------
-- 8. Public tracking (no PII beyond first name + city)
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.track_shipment(p_tracking_number TEXT)
RETURNS JSONB
LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_ship public.shipments;
BEGIN
  SELECT * INTO v_ship FROM public.shipments
   WHERE tracking_number = upper(trim(p_tracking_number));
  IF v_ship.id IS NULL THEN
    RETURN NULL;
  END IF;

  RETURN jsonb_build_object(
    'tracking_number', v_ship.tracking_number,
    'status', v_ship.status,
    'service_level', v_ship.service_level,
    'parcel_count', v_ship.parcel_count,
    'recipient', split_part(v_ship.recipient_name, ' ', 1),
    'destination_city', COALESCE(v_ship.delivery_address->>'city', v_ship.delivery_address->>'suburb'),
    'promised_by', v_ship.promised_by,
    'delivered_at', v_ship.delivered_at,
    'attempt_count', v_ship.attempt_count,
    'created_at', v_ship.created_at,
    'events', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
               'status', e.status,
               'at', e.created_at,
               'location', h.name
             ) ORDER BY e.created_at DESC)
        FROM public.shipment_events e
        LEFT JOIN public.logistics_hubs h ON h.id = e.hub_id
       WHERE e.shipment_id = v_ship.id
    ), '[]'::jsonb)
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.track_shipment(TEXT) TO anon, authenticated;

-- ---------------------------------------------------------------------------
-- 9. Proof-of-delivery photos (private bucket; drivers write under their uid)
-- ---------------------------------------------------------------------------
INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
VALUES ('delivery-proofs', 'delivery-proofs', false, 5242880, ARRAY['image/jpeg', 'image/png', 'image/webp'])
ON CONFLICT (id) DO NOTHING;

DROP POLICY IF EXISTS "Drivers upload delivery proofs" ON storage.objects;
CREATE POLICY "Drivers upload delivery proofs" ON storage.objects
  FOR INSERT TO authenticated
  WITH CHECK (
    bucket_id = 'delivery-proofs'
    AND (storage.foldername(name))[1] = (SELECT auth.uid())::text
    AND EXISTS (SELECT 1 FROM public.drivers WHERE user_id = (SELECT auth.uid()))
  );

DROP POLICY IF EXISTS "Drivers and staff read delivery proofs" ON storage.objects;
CREATE POLICY "Drivers and staff read delivery proofs" ON storage.objects
  FOR SELECT TO authenticated
  USING (
    bucket_id = 'delivery-proofs'
    AND ((storage.foldername(name))[1] = (SELECT auth.uid())::text OR (SELECT public.is_logistics_staff()))
  );

-- ---------------------------------------------------------------------------
-- 10. Realtime
-- ---------------------------------------------------------------------------
DO $$
DECLARE
  t TEXT;
BEGIN
  FOREACH t IN ARRAY ARRAY['shipments', 'shipment_events', 'delivery_routes', 'route_stops'] LOOP
    IF NOT EXISTS (
      SELECT 1 FROM pg_publication_tables
       WHERE pubname = 'supabase_realtime' AND schemaname = 'public' AND tablename = t
    ) THEN
      EXECUTE format('ALTER PUBLICATION supabase_realtime ADD TABLE public.%I', t);
    END IF;
  END LOOP;
END;
$$;

-- >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>> 20261116130000_logistics_upgrades.sql
-- =============================================================================
-- 1145 Logistics — upgrades
--   1. (driver positions come from the platform: driver_publish_position)
--   2. Marketplace delivery jobs ⇄ shipments (tracking, routing, notifications)
--   3. Consumer parcel booking with server-side quote
--   4. Recipient notifications (pg_net → logistics-notify, idempotent)
--   5. Server-verified proof of delivery for on-demand jobs
-- =============================================================================

-- ---------------------------------------------------------------------------
-- 2. Marketplace delivery jobs ⇄ shipments
-- ---------------------------------------------------------------------------
ALTER TABLE public.shipments
  ADD COLUMN IF NOT EXISTS source TEXT NOT NULL DEFAULT 'ops',
  ADD COLUMN IF NOT EXISTS payment_status TEXT NOT NULL DEFAULT 'not_required';

ALTER TABLE public.shipments DROP CONSTRAINT IF EXISTS shipments_source_check;
ALTER TABLE public.shipments ADD CONSTRAINT shipments_source_check
  CHECK (source IN ('ops', 'csv_import', 'marketplace', 'consumer', 'api'));
ALTER TABLE public.shipments DROP CONSTRAINT IF EXISTS shipments_payment_status_check;
ALTER TABLE public.shipments ADD CONSTRAINT shipments_payment_status_check
  CHECK (payment_status IN ('not_required', 'unpaid', 'paid', 'refunded'));

CREATE UNIQUE INDEX IF NOT EXISTS shipments_delivery_job_key
  ON public.shipments (delivery_job_id) WHERE delivery_job_id IS NOT NULL;

ALTER TABLE public.delivery_jobs ADD COLUMN IF NOT EXISTS proof JSONB;

-- New marketplace delivery job → shipment (tracking number, timeline, SMS).
CREATE OR REPLACE FUNCTION public.delivery_job_create_shipment()
RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_order RECORD;
  v_store TEXT;
  v_addr JSONB;
BEGIN
  IF NEW.order_id IS NULL OR EXISTS (SELECT 1 FROM public.shipments WHERE delivery_job_id = NEW.id) THEN
    RETURN NEW;
  END IF;

  SELECT o.id, o.user_id, o.shipping_address, o.total INTO v_order FROM public.orders o WHERE o.id = NEW.order_id;
  IF v_order.id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT s.name INTO v_store
    FROM public.order_items oi JOIN public.stores s ON s.id = oi.store_id
   WHERE oi.order_id = NEW.order_id
   LIMIT 1;

  v_addr := COALESCE(v_order.shipping_address, '{}'::jsonb);

  INSERT INTO public.shipments (
    reference, order_id, delivery_job_id, customer_user_id,
    sender_name, recipient_name, recipient_phone, recipient_email,
    pickup_address, delivery_address, service_level, status, source,
    promised_by, created_by, notes
  ) VALUES (
    'ORD-' || upper(left(NEW.order_id::text, 8)), NEW.order_id, NEW.id, v_order.user_id,
    COALESCE(v_store, NEW.pickup_address->>'street', 'Merchant'),
    COALESCE(NULLIF(v_addr->>'name', ''), NULLIF(v_addr->>'full_name', ''), 'Customer'),
    COALESCE(NULLIF(v_addr->>'phone', ''), NULLIF(v_addr->>'phone_number', '')),
    NULLIF(v_addr->>'email', ''),
    NEW.pickup_address, NEW.delivery_address,
    CASE WHEN NEW.priority = 'urgent' THEN 'same_day' ELSE 'next_day' END,
    CASE NEW.status WHEN 'pending' THEN 'awaiting_pickup' WHEN 'accepted' THEN 'awaiting_pickup'
                    WHEN 'picked_up' THEN 'picked_up' WHEN 'in_transit' THEN 'out_for_delivery'
                    WHEN 'delivered' THEN 'delivered' ELSE 'awaiting_pickup' END,
    'marketplace',
    now() + CASE WHEN NEW.priority = 'urgent' THEN interval '10 hours' ELSE interval '30 hours' END,
    auth.uid(), NEW.notes
  );
  RETURN NEW;
EXCEPTION WHEN others THEN
  RAISE LOG 'delivery_job_create_shipment failed for %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_delivery_job_create_shipment ON public.delivery_jobs;
CREATE TRIGGER trg_delivery_job_create_shipment
  AFTER INSERT ON public.delivery_jobs
  FOR EACH ROW EXECUTE FUNCTION public.delivery_job_create_shipment();

-- On-demand job progress → shipment status. Routed jobs are excluded: the
-- route-run RPCs update both sides themselves.
CREATE OR REPLACE FUNCTION public.delivery_job_sync_shipment()
RETURNS TRIGGER
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_status TEXT;
BEGIN
  IF NEW.route_id IS NOT NULL OR NEW.status IS NOT DISTINCT FROM OLD.status THEN
    RETURN NEW;
  END IF;

  v_status := CASE NEW.status
    WHEN 'picked_up' THEN 'picked_up'
    WHEN 'in_transit' THEN 'out_for_delivery'
    WHEN 'delivered' THEN 'delivered'
    WHEN 'failed' THEN 'failed_attempt'
    WHEN 'returned' THEN 'returned'
    WHEN 'cancelled' THEN 'cancelled'
    WHEN 'pending' THEN 'awaiting_pickup'
    ELSE NULL END;
  IF v_status IS NULL THEN
    RETURN NEW;
  END IF;

  PERFORM set_config('logistics.event_driver', COALESCE(NEW.driver_id::text, ''), true);
  PERFORM set_config('logistics.event_notes', COALESCE(NEW.failure_reason, ''), true);

  UPDATE public.shipments s
     SET status = CASE
           WHEN v_status = 'failed_attempt' AND s.attempt_count + 1 >= s.max_attempts THEN 'returning'
           ELSE v_status END,
         attempt_count = s.attempt_count + CASE WHEN v_status = 'failed_attempt' THEN 1 ELSE 0 END,
         last_failure_reason = CASE WHEN v_status = 'failed_attempt' THEN NEW.failure_reason ELSE s.last_failure_reason END,
         picked_up_at = CASE WHEN v_status = 'picked_up' THEN now() ELSE s.picked_up_at END,
         delivered_at = CASE WHEN v_status = 'delivered' THEN COALESCE(NEW.actual_delivery_time, now()) ELSE s.delivered_at END
   WHERE s.delivery_job_id = NEW.id
     AND s.status NOT IN ('delivered', 'returned', 'cancelled');
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_delivery_job_sync_shipment ON public.delivery_jobs;
CREATE TRIGGER trg_delivery_job_sync_shipment
  AFTER UPDATE OF status ON public.delivery_jobs
  FOR EACH ROW EXECUTE FUNCTION public.delivery_job_sync_shipment();

-- Backfill shipments for open marketplace jobs that predate this migration.
INSERT INTO public.shipments (
  reference, order_id, delivery_job_id, customer_user_id, sender_name, recipient_name, recipient_phone,
  pickup_address, delivery_address, service_level, status, source, notes
)
SELECT 'ORD-' || upper(left(j.order_id::text, 8)), j.order_id, j.id, o.user_id,
       COALESCE(j.pickup_address->>'street', 'Merchant'),
       COALESCE(NULLIF(o.shipping_address->>'name', ''), 'Customer'),
       NULLIF(o.shipping_address->>'phone', ''),
       j.pickup_address, j.delivery_address, 'next_day',
       CASE j.status WHEN 'picked_up' THEN 'picked_up' WHEN 'in_transit' THEN 'out_for_delivery' ELSE 'awaiting_pickup' END,
       'marketplace', j.notes
  FROM public.delivery_jobs j
  JOIN public.orders o ON o.id = j.order_id
 WHERE j.status IN ('pending', 'assigned', 'accepted', 'picked_up', 'in_transit')
   AND NOT EXISTS (SELECT 1 FROM public.shipments s WHERE s.delivery_job_id = j.id);

-- ---------------------------------------------------------------------------
-- 3. Consumer parcel booking
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.logistics_distance_km(a JSONB, b JSONB)
RETURNS NUMERIC
LANGUAGE plpgsql IMMUTABLE
AS $$
DECLARE
  lat1 NUMERIC := NULLIF(a->>'lat', '')::numeric;
  lng1 NUMERIC := NULLIF(a->>'lng', '')::numeric;
  lat2 NUMERIC := NULLIF(b->>'lat', '')::numeric;
  lng2 NUMERIC := NULLIF(b->>'lng', '')::numeric;
BEGIN
  IF lat1 IS NULL OR lng1 IS NULL OR lat2 IS NULL OR lng2 IS NULL THEN
    RETURN NULL;
  END IF;
  RETURN round((2 * 6371 * asin(sqrt(
    power(sin(radians(lat2 - lat1) / 2), 2) +
    cos(radians(lat1)) * cos(radians(lat2)) * power(sin(radians(lng2 - lng1) / 2), 2)
  )) * 1.3)::numeric, 1);  -- road factor
END;
$$;

-- Tariff: base by size + per-km, scaled by service level. Quote is advisory;
-- book_parcel recomputes it server-side so the client can't set its own price.
CREATE OR REPLACE FUNCTION public.quote_parcel(p_pickup JSONB, p_delivery JSONB, p_size TEXT, p_service_level TEXT)
RETURNS JSONB
LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_km NUMERIC := public.logistics_distance_km(p_pickup, p_delivery);
  v_base NUMERIC := CASE p_size WHEN 'small' THEN 45 WHEN 'medium' THEN 65 WHEN 'large' THEN 95 WHEN 'xl' THEN 150 ELSE NULL END;
  v_per_km NUMERIC := CASE p_size WHEN 'xl' THEN 9 WHEN 'large' THEN 7 ELSE 5.5 END;
  v_mult NUMERIC := CASE p_service_level WHEN 'express' THEN 1.8 WHEN 'same_day' THEN 1.35 WHEN 'next_day' THEN 1.0 WHEN 'standard' THEN 0.85 ELSE NULL END;
  v_fee NUMERIC;
  v_ip TEXT := public.logistics_client_ip();
BEGIN
  -- Public endpoint: 120 quotes / minute / IP (server-side callers have no IP).
  IF v_ip IS NOT NULL AND NOT public.logistics_rate_hit('quote:' || v_ip, 120, 60) THEN
    RAISE EXCEPTION 'rate_limited' USING ERRCODE = 'P0429';
  END IF;
  IF v_base IS NULL OR v_mult IS NULL THEN
    RAISE EXCEPTION 'invalid_size_or_service';
  END IF;
  IF v_km IS NULL THEN
    RAISE EXCEPTION 'address_not_geocoded';
  END IF;
  IF v_km > 400 THEN
    RAISE EXCEPTION 'distance_out_of_range';
  END IF;
  v_fee := round((v_base + v_km * v_per_km) * v_mult, 0);
  RETURN jsonb_build_object(
    'distance_km', v_km,
    'fee', v_fee,
    'currency', 'ZAR',
    'promised_by', now() + CASE p_service_level
      WHEN 'express' THEN interval '2 hours'
      WHEN 'same_day' THEN interval '10 hours'
      WHEN 'next_day' THEN interval '30 hours'
      ELSE interval '72 hours' END
  );
END;
$$;

CREATE OR REPLACE FUNCTION public.book_parcel(
  p_pickup JSONB,
  p_delivery JSONB,
  p_sender_name TEXT,
  p_sender_phone TEXT,
  p_recipient_name TEXT,
  p_recipient_phone TEXT,
  p_size TEXT,
  p_service_level TEXT,
  p_notes TEXT DEFAULT NULL,
  p_require_otp BOOLEAN DEFAULT true,
  p_delivery_window TEXT DEFAULT 'any',
  p_pickup_point_id UUID DEFAULT NULL
)
RETURNS JSONB
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_uid UUID := auth.uid();
  v_quote JSONB;
  v_job UUID;
  v_ship public.shipments;
  v_weight NUMERIC := CASE p_size WHEN 'small' THEN 2 WHEN 'medium' THEN 5 WHEN 'large' THEN 15 ELSE 30 END;
  -- Windows apply to planned services; express/same-day go as soon as possible.
  v_window TEXT := CASE WHEN p_service_level IN ('next_day', 'standard') AND p_delivery_window IN ('morning', 'afternoon', 'evening')
                        THEN p_delivery_window ELSE 'any' END;
  v_promise TIMESTAMPTZ;
  v_point public.logistics_hubs;
  v_delivery JSONB := p_delivery;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501';
  END IF;
  IF coalesce(trim(p_sender_name), '') = '' OR coalesce(trim(p_recipient_name), '') = ''
     OR coalesce(trim(p_recipient_phone), '') = '' THEN
    RAISE EXCEPTION 'missing_contact_details';
  END IF;
  IF (SELECT count(*) FROM public.shipments WHERE created_by = v_uid AND source = 'consumer'
        AND created_at > now() - interval '24 hours') >= 20 THEN
    RAISE EXCEPTION 'daily_booking_limit';
  END IF;

  -- Collect from a pickup point / locker instead of a door: the point is the
  -- delivery address and the fee is 20% lower (consolidated drop).
  IF p_pickup_point_id IS NOT NULL THEN
    SELECT * INTO v_point FROM public.logistics_hubs
     WHERE id = p_pickup_point_id AND is_active AND hub_type IN ('pickup_point', 'locker') AND lat IS NOT NULL;
    IF v_point.id IS NULL THEN
      RAISE EXCEPTION 'invalid_pickup_point';
    END IF;
    IF p_service_level = 'express' THEN
      RAISE EXCEPTION 'express_not_available_to_pickup_points';
    END IF;
    v_delivery := coalesce(v_point.address, '{}'::jsonb) || jsonb_build_object('lat', v_point.lat, 'lng', v_point.lng, 'pickup_point', v_point.name);
  END IF;

  v_quote := public.quote_parcel(p_pickup, v_delivery, p_size, p_service_level);
  IF v_point.id IS NOT NULL THEN
    v_quote := jsonb_set(v_quote, '{fee}', to_jsonb(round((v_quote->>'fee')::numeric * 0.8, 0)));
  END IF;
  v_promise := (v_quote->>'promised_by')::timestamptz;
  IF v_window <> 'any' THEN
    -- Promise the end of the chosen window on the promised day.
    SELECT window_end INTO v_promise
      FROM public.logistics_window_bounds(v_window, (v_promise AT TIME ZONE 'Africa/Johannesburg')::date);
  END IF;

  -- Fast services go straight to the on-demand dispatch queue; slower ones are
  -- consolidated onto planned routes from the ops console.
  IF p_service_level IN ('express', 'same_day') THEN
    INSERT INTO public.delivery_jobs (pickup_address, delivery_address, status, priority, distance_km, notes)
    VALUES (p_pickup, v_delivery, 'pending',
            CASE WHEN p_service_level = 'express' THEN 'urgent' ELSE 'normal' END,
            (v_quote->>'distance_km')::numeric, p_notes)
    RETURNING id INTO v_job;
  END IF;

  INSERT INTO public.shipments (
    delivery_job_id, customer_user_id, created_by,
    sender_name, sender_phone, recipient_name, recipient_phone,
    pickup_address, delivery_address, service_level, status, source,
    weight_kg, shipping_fee, payment_status, require_otp, promised_by, notes, metadata, delivery_window, destination_hub_id
  ) VALUES (
    v_job, v_uid, v_uid,
    trim(p_sender_name), nullif(trim(p_sender_phone), ''), trim(p_recipient_name), trim(p_recipient_phone),
    p_pickup, v_delivery, p_service_level, 'awaiting_pickup', 'consumer',
    v_weight, (v_quote->>'fee')::numeric, 'unpaid', coalesce(p_require_otp, true),
    v_promise, nullif(trim(p_notes), ''),
    jsonb_build_object('size', p_size, 'distance_km', v_quote->'distance_km'), CASE WHEN v_point.id IS NULL THEN v_window ELSE 'any' END, v_point.id
  ) RETURNING * INTO v_ship;

  RETURN jsonb_build_object(
    'id', v_ship.id,
    'tracking_number', v_ship.tracking_number,
    'fee', v_ship.shipping_fee,
    'promised_by', v_ship.promised_by,
    'delivery_otp', CASE WHEN v_ship.require_otp THEN v_ship.delivery_otp END
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.quote_parcel(JSONB, JSONB, TEXT, TEXT) TO authenticated, anon;
GRANT EXECUTE ON FUNCTION public.book_parcel(JSONB, JSONB, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, TEXT, BOOLEAN, TEXT, UUID) TO authenticated;

-- Senders can cancel their own booking until it's collected.
CREATE OR REPLACE FUNCTION public.cancel_my_parcel(p_shipment_id UUID)
RETURNS VOID
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_ship public.shipments;
BEGIN
  SELECT * INTO v_ship FROM public.shipments WHERE id = p_shipment_id FOR UPDATE;
  IF v_ship.id IS NULL OR v_ship.customer_user_id IS DISTINCT FROM auth.uid() OR v_ship.source <> 'consumer' THEN
    RAISE EXCEPTION 'not_found' USING ERRCODE = '42501';
  END IF;
  IF v_ship.status NOT IN ('created', 'awaiting_pickup') THEN
    RAISE EXCEPTION 'already_collected';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.route_stops rs JOIN public.delivery_routes r ON r.id = rs.route_id
     WHERE rs.shipment_id = v_ship.id AND r.status IN ('dispatched', 'in_progress')
  ) THEN
    RAISE EXCEPTION 'already_dispatched';
  END IF;
  PERFORM set_config('logistics.event_notes', 'Cancelled by sender', true);
  UPDATE public.shipments SET status = 'cancelled' WHERE id = v_ship.id;
  IF v_ship.delivery_job_id IS NOT NULL THEN
    UPDATE public.delivery_jobs SET status = 'cancelled' WHERE id = v_ship.delivery_job_id AND status IN ('pending', 'accepted');
  END IF;
  UPDATE public.route_stops SET status = 'skipped', failure_reason = 'Cancelled by sender'
   WHERE shipment_id = v_ship.id AND status = 'pending';
END;
$$;
GRANT EXECUTE ON FUNCTION public.cancel_my_parcel(UUID) TO authenticated;

